package edu.ku.commerce.omnichannel_commerce.common.security;
import io.jsonwebtoken.*; import io.jsonwebtoken.security.Keys; import java.nio.charset.StandardCharsets; import java.time.*; import java.util.*; import javax.crypto.SecretKey; import org.springframework.beans.factory.annotation.*; import org.springframework.stereotype.Service;
@Service public class JwtService { private final SecretKey key; private final long minutes; public JwtService(@Value("${app.jwt.secret}") String secret,@Value("${app.jwt.access-minutes}") long minutes){this.key=Keys.hmacShaKeyFor(secret.getBytes(StandardCharsets.UTF_8));this.minutes=minutes;} public String issue(String email,String role){return Jwts.builder().subject(email).claim("role",role).issuedAt(new Date()).expiration(Date.from(Instant.now().plusSeconds(minutes*60))).signWith(key).compact();} public Claims claims(String token){return Jwts.parser().verifyWith(key).build().parseSignedClaims(token).getPayload();} }
